/**
 * Avatar utility — returns human face images from the Human Faces Dataset
 * stored in /public/avatars/Human Faces Dataset/
 *
 * Gender-aware: matches female faces to female names and male faces to male names.
 * Uses gender_manifest.json (generated by classify_genders.py) for accurate matching.
 * Falls back to index-based split (odd=male, even=female) if manifest is absent.
 *
 * Dan's profile pic lives in /public/my-avatar/profile.jpg
 */

// ─── Constants ─────────────────────────────────────────────────────────────

const REAL_BASE = '/avatars/Human Faces Dataset/Real Images/';
const AI_BASE = '/avatars/Human Faces Dataset/AI-Generated Images/';

// How many images are in each folder (used as fallback when manifest not loaded)
const REAL_COUNT = 5000;



// ─── Gender manifest (loaded lazily at runtime) ─────────────────────────────

interface GenderManifest {
    real: { male: string[]; female: string[] };
    ai: { male: string[]; female: string[] };
}

let _manifest: GenderManifest | null = null;
let _manifestLoading = false;
let _manifestCallbacks: Array<() => void> = [];

async function loadManifest(): Promise<GenderManifest | null> {
    if (_manifest) return _manifest;
    if (_manifestLoading) {
        return new Promise(resolve => {
            _manifestCallbacks.push(() => resolve(_manifest));
        });
    }
    _manifestLoading = true;
    try {
        const res = await fetch('/avatars/gender_manifest.json');
        if (!res.ok) throw new Error('not found');
        _manifest = await res.json();
        _manifestCallbacks.forEach(cb => cb());
        return _manifest;
    } catch {
        _manifestCallbacks.forEach(cb => cb());
        return null;
    }
}

