export function guessGender(name: string): 'male' | 'female' | 'unknown' {
    const first = name.trim().split(/\s+/)[0].toLowerCase();
    if (FEMALE_NAMES.has(first)) return 'female';
    if (MALE_NAMES.has(first)) return 'male';
    return 'unknown';
}

// ─── Hash utility ─────────────────────────────────────────────────────────

function hashCode(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = (Math.imul(31, hash) + str.charCodeAt(i)) | 0;
    }
    return Math.abs(hash);
}

// ─── Fallback (no manifest) — range-based gender split ───────────────────
// Files 1–2500 = female pool, 2501–5000 = male pool (deterministic, consistent)
function fallbackAvatar(seed: string, gender: 'male' | 'female' | 'unknown'): string {
    const pad = (n: number) => String(n).padStart(6, '0');
    const halfCount = Math.floor(REAL_COUNT / 2); // 2500
    const slot = hashCode(seed) % halfCount;       // 0–2499
    let idx: number;
    if (gender === 'female') {
        idx = slot + 1;             // 1–2500  → female half
    } else {
        idx = slot + halfCount + 1; // 2501–5000 → male half
    }
    return `${REAL_BASE}${pad(Math.min(idx, REAL_COUNT))}.jpg`;
}

// ─── Public API ────────────────────────────────────────────────────────────

/**
 * Get an avatar URL matched to the gender of the given name.
 * Async — uses the manifest for accuracy, falls back to parity split.
 */
export async function getGenderedAvatar(name: string): Promise<string> {
    const gender = guessGender(name);
    const manifest = await loadManifest();

    if (manifest) {
        const pool = gender === 'female'
            ? [...manifest.real.female, ...manifest.ai.female]
            : [...manifest.real.male, ...manifest.ai.male];

        if (pool.length > 0) {
            const idx = hashCode(name) % pool.length;
            const fname = pool[idx];
            // Determine which base path to use
            const base = manifest.real.male.includes(fname) || manifest.real.female.includes(fname)
                ? REAL_BASE
                : AI_BASE;
            return `${base}${fname}`;
        }
    }

    return fallbackAvatar(name, gender);
}

/**
 * Synchronous version — uses fallback only (no manifest).
 * Use this when you can't await.
 */
export function getSeededAvatar(seed: string): string {
    const gender = guessGender(seed);
    return fallbackAvatar(seed, gender);
}

/**
 * Pick a random avatar from the full Real Images pool.
 */
export function getRandomAvatar(): string {
    const idx = Math.floor(Math.random() * REAL_COUNT) + 1;
    return `${REAL_BASE}${String(idx).padStart(6, '0')}.jpg`;
}

/**
 * Get N unique random avatars.
 */
export function getRandomAvatars(count: number): string[] {
    const indices = new Set<number>();
    while (indices.size < Math.min(count, REAL_COUNT)) {
        indices.add(Math.floor(Math.random() * REAL_COUNT) + 1);
    }
    return Array.from(indices).map(i => `${REAL_BASE}${String(i).padStart(6, '0')}.jpg`);
}

/** Dan's own profile picture. */
export const MY_AVATAR = '/my-avatar/profile.jpg';
